import { test, expect } from '@playwright/test';
import { PARENT_B, expectDocOpen, visibleText } from './legal-docs.helpers';

test.use({ storageState: PARENT_B });

test.describe('Юридические документы — родитель под входом', () => {
  test('Путь к условиям из настроек: /settings → /privacy → «תנאי השימוש» @desktop @prod-safe #d7fe2c', async ({ page }) => {
    await page.goto('/settings');
    // Figma E7 178-4459, блок «פרטיות ונתונים»
    await visibleText(page, 'מדיניות פרטיות ותנאי שימוש').click();
    await page.waitForURL(/\/privacy$/);

    // Ссылка добавлена в /privacy (комментарий программиста 01.11)
    const termsLink = visibleText(page, 'תנאי השימוש');
    await expect(termsLink).toBeVisible();
    await termsLink.click();
    await page.waitForURL(/\/consent\?doc=terms$/);
    await expectDocOpen(page, 'terms');
  });
});
